args.input:
const text=(p,name,content,size=14,color="#18181B",weight="normal")=>Insert(p,{type:"text",name,content,fontFamily:"Inter",fontSize:size,fontWeight:weight,fill:color,textGrowth:"fixed-width",width:"fill_container",lineHeight:1.45});
for(const [source,device,width,height,y] of [["YinY7","desktop1440",1440,1000,1100],["U5hcvC","mobile390",390,1040,2300]]){
const review=Copy(source,document,{name:"A · "+device+" · Confirm",x:3200,y,placeholder:true,metadata:{type:"screen",state:"confirmation",device}});
const overlay=Insert(review,{type:"frame",name:"Confirmation overlay",layoutPosition:"absolute",x:0,y:0,width,height,layout:"vertical",alignItems:"center",justifyContent:"center",fill:"#18181B66"});
const dialog=Insert(overlay,{type:"frame",name:"Review changes dialog",width:device==="desktop1440"?480:350,layout:"vertical",padding:24,gap:20,fill:"#FFFFFF",cornerRadius:12,stroke:"#E4E4E7",strokeWidth:1,metadata:{type:"dialog",modal:true,label:"Review changes"}});
text(dialog,"Dialog title","Review changes",24,"#18181B","600");
text(dialog,"Dialog description","Apply these preferences in this local prototype?",14,"#52525B");
const values=Insert(dialog,{type:"frame",name:"Review values",layout:"vertical",width:"fill_container",gap:16,padding:16,fill:"#FAFAFA",cornerRadius:6});
for(const [label,value] of [["Email address","alex@example.test"],["Email notifications","On"],["Frequency","Daily → Weekly"]]){const row=Insert(values,{type:"frame",name:label+" review row",layout:"vertical",width:"fill_container",gap:4});text(row,label+" review label",label,12,"#71717A");text(row,label+" review value",value,14,"#18181B","500");}
text(dialog,"Local confirmation note","Only local demo state changes. No email is sent.",12,"#71717A");
const actions=Insert(dialog,{type:"frame",name:"Dialog actions",layout:device==="desktop1440"?"horizontal":"vertical",width:"fill_container",gap:12,justifyContent:"end"});
for(const [label,primary] of [["Back",false],["Apply changes",true]]){const b=Insert(actions,{type:"frame",name:label+" button",layout:"horizontal",width:device==="desktop1440"?"fit_content":"fill_container",padding:[12,18],justifyContent:"center",fill:primary?"#18181B":"#FFFFFF",stroke:primary?"#18181B":"#D4D4D8",strokeWidth:1,cornerRadius:6,metadata:{type:"action",action:primary?"apply-local-draft":"close-keep-draft"}});Insert(b,{type:"text",name:label+" label",content:label,fontFamily:"Inter",fontSize:14,fontWeight:"500",fill:primary?"#FFFFFF":"#18181B"});}
Update(review,{placeholder:false});
Print({device,review,dialog});
}
